$ErrorActionPreference='Stop';$hub=Split-Path (Split-Path $PSScriptRoot);$taskSchema=Get-Content -Raw (Join-Path $hub 'ai5\schemas\zero-task.schema.json')|ConvertFrom-Json;$resultSchema=Get-Content -Raw (Join-Path $hub 'ai5\schemas\zero-result.schema.json')|ConvertFrom-Json
$required=@('TASK_ID','PROJECT_ID','PURPOSE','PRIORITY','CANONICAL_REPO','CANONICAL_BRANCH','ALLOWED_ACTIONS','PROHIBITED_ACTIONS','OWNER_GATE_POLICY','ASSIGNEE','FALLBACK','EXPECTED_RESULT','CORRELATION_ID')
if(@($required|Where-Object{$_-notin@($taskSchema.required)}).Count){throw 'ZERO_TASK_SCHEMA required fields missing'};if($taskSchema.additionalProperties-ne$false-or$resultSchema.additionalProperties-ne$false){throw 'schemas must fail closed'}
$task=[ordered]@{TASK_ID='task-1';PROJECT_ID='ai5-hub';PURPOSE='safe test';PRIORITY='P0';CANONICAL_REPO='daimon-app/daimon-sales';CANONICAL_BRANCH='main';ALLOWED_ACTIONS=@('READ');PROHIBITED_ACTIONS=@('PUBLISH');OWNER_GATE_POLICY='OWNER_ONLY_EXTERNAL_EFFECTS';ASSIGNEE='codex';FALLBACK=@('zero');EXPECTED_RESULT=@{status='PASS'};CORRELATION_ID='corr-1'}
foreach($name in $required){if(!$task.Contains($name)){throw "valid task missing $name"}};$bad=[ordered]@{};foreach($entry in $task.GetEnumerator()){$bad[$entry.Key]=$entry.Value};$bad.Remove('CORRELATION_ID');if(@($required|Where-Object{!$bad.Contains($_)}).Count-ne1){throw 'missing field validation failed'}
if('WAITING_OWNER_AUTH'-notin@($resultSchema.properties.STATUS.enum)-or'NOT_WIRED'-notin@($resultSchema.properties.STATUS.enum)){throw 'strict result states missing'};'ZERO_TASK_RESULT_SCHEMA_TESTS_OK'
